import {defaultDetails,extraBodyShape,extraBodyArt,cabinSurface,extraCabin,extraLegs,extraEngine,patternArt,flamePaths} from './kit.js?v=expanded-1';
import {emojiOptions,CATALOG,palette,normalize} from './model.js?v=flight-1';
let serial=0;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bodyShape(c){return extraBodyShape(c)||({descent:'M-70 0L-52-15H52L70 0V56L48 69H-48L-70 56Z',tank:'M-57 8Q-57-19 0-19Q57-19 57 8V45Q57 70 0 70Q-57 70-57 45Z',cargo:'M-68-13H68V66H-68Z',truss:'M-64-9H64V63H-64Z',saucer:'M-94 27Q-67-15 0-15Q67-15 94 27Q65 66 0 66Q-65 66-94 27Z',toaster:'M-62-13Q-70-13-70-4V58Q-70 66-60 66H60Q70 66 70 58V-4Q70-13 62-13Z',donut:'M-66 25A66 45 0 1 0 66 25A66 45 0 1 0-66 25Z',cloud:'M-70 54C-103 44-87 9-62 12C-65-18-19-24-7-3C20-26 61-17 62 7C96-1 108 53 72 58Z'})[c.body]||''}
function bodyArt(c,p,id){const shell=`<path d="${bodyShape(c)}" fill="url(#${id}hull)" stroke="#18252a" stroke-width="3"/>`;const details=({descent:`<path d="M-66 1L-48-10H48L66 1V15H-66Z" fill="${p.secondary}" opacity=".55"/><path d="M-50 18V56M-25 18V63M0 18V63M25 18V63M50 18V56" stroke="${p.dark}" opacity=".35"/><path d="M-63 20H63M-62 53H62" stroke="${p.dark}" stroke-width="4"/><path d="M-53 23L-42 48-26 26-8 48 12 24 33 48 52 25" stroke="#fff" opacity=".12" fill="none"/>`,tank:`<ellipse cy="4" rx="57" ry="16" fill="${p.secondary}" opacity=".45"/><path d="M-57 12Q0 38 57 12M-57 44Q0 70 57 44" fill="none" stroke="${p.dark}" stroke-width="5"/><path d="M-33 16V47M33 16V47" stroke="#fff" opacity=".3" stroke-width="3"/>`,cargo:`<path d="M-67-12H67V1H-67Z" fill="${p.secondary}"/><path d="M-66 8H-43V63H-66M43 8H66V63H43" fill="${p.dark}" opacity=".5"/><path d="M-36 4V62M36 4V62" stroke="${p.secondary}" stroke-width="5"/><path d="M-26 48H26" stroke="${p.dark}" stroke-width="2"/>`,truss:`<path d="M-57 0H57V56H-57Z" fill="#1b2d34"/><ellipse cx="-24" cy="27" rx="16" ry="27" fill="${p.secondary}"/><ellipse cx="24" cy="27" rx="16" ry="27" fill="${p.secondary}"/><path d="M-61-7L61 61M61-7L-61 61M-61 26H61" stroke="${p.primary}" stroke-width="7"/><rect x="-24" y="10" width="48" height="36" rx="4" fill="${p.primary}"/>`,saucer:`<ellipse cy="27" rx="94" ry="18" fill="${p.secondary}"/><path d="M-87 37Q0 68 87 37" stroke="${p.dark}" fill="none" stroke-width="4"/>${[-65,-35,0,35,65].map(x=>`<circle cx="${x}" cy="30" r="4" fill="${p.glass}"/>`).join('')}`,toaster:`<path d="M-68-10H68V4H-68Z" fill="${p.secondary}"/><path d="M-45-6H-8M8-6H45" stroke="#28383d" stroke-width="5" stroke-linecap="round"/><rect x="-52" y="17" width="76" height="31" rx="5" fill="${p.secondary}" opacity=".4"/><circle cx="48" cy="25" r="7" fill="#293b43"/><path d="M48 32V49" stroke="#293b43" stroke-width="4"/>`,donut:`<ellipse cy="25" rx="62" ry="40" fill="#dfa5b6"/><ellipse cy="25" rx="23" ry="13" fill="#263d45" stroke="#ac7884" stroke-width="6"/>${[-45,-15,24,43].map((x,i)=>`<path d="M${x} ${i%2?-1:47}l8 3" stroke="${['#ffe082','#a0dbce','#ede6cd','#9f98d5'][i]}" stroke-width="4"/>`).join('')}`,cloud:`<path d="M-64 32Q-39 42-18 35M13 42Q40 47 64 35" stroke="${p.secondary}" fill="none" stroke-width="4" opacity=".6"/>`})[c.body]||extraBodyArt(c,p);return shell+details+`<path d="M-42 63H42" stroke="${p.dark}" stroke-width="3"/>`}
function cabinArt(c,p,id){const extra=extraCabin(c,p,id);if(extra!==null)return extra;const emoji=emojiOptions.find(o=>o.id===c.cabin);if(emoji)return `<path d="M-36-14H36V-3H-36Z" fill="${p.secondary}"/><text x="0" y="-22" text-anchor="middle" font-size="112" font-family="Apple Color Emoji,Segoe UI Emoji,Noto Color Emoji,sans-serif">${emoji.glyph}</text>`;const metal=`url(#${id}metal)`,glass=`url(#${id}glass)`;return ({cabin:`<path d="M-45-16V-65L-26-93H25L45-65V-16Z" fill="${metal}" stroke="#1c2c33" stroke-width="3"/><path d="M-28-66L-17-82H17L28-66V-43H-28Z" fill="${glass}" stroke="#3b5664" stroke-width="4"/><path d="M-45-32H45V-16H-45Z" fill="${p.primary}"/><path d="M-34-71L-26-83M-36-57V-42" stroke="#fff" opacity=".45" stroke-width="2"/>`,bubble:`<path d="M-51-16V-34A51 56 0 0 1 51-34V-16Z" fill="${glass}" stroke="${p.secondary}" stroke-width="4"/><path d="M-33-49Q-30-72-10-77" fill="none" stroke="#d3f5f3" opacity=".7" stroke-width="4" stroke-linecap="round"/><path d="M-55-20H55V-9H-55Z" fill="${metal}"/>`,pod:`<path d="M-33-17L-39-69-18-101H18L39-69 33-17Z" fill="${metal}" stroke="#22343c" stroke-width="3"/><path d="M-21-77H21L27-57H-27Z" fill="${glass}" stroke="#4b6574" stroke-width="4"/><path d="M-36-42H36" stroke="${p.primary}" stroke-width="8"/><path d="M-18-100V-112" stroke="#aebfc5" stroke-width="3"/>`,dish:`<path d="M-25-13L-11-60H11L25-13Z" fill="${metal}"/><g transform="translate(0 -73) rotate(-17)"><path d="M-58-24Q0 50 58-24Q0-8-58-24Z" fill="${metal}" stroke="#334c58" stroke-width="3"/><path d="M0 17V-34M-45-18L0-34 45-18" fill="none" stroke="#90a8b4" stroke-width="2"/><circle cy="-35" r="5" fill="${p.primary}"/></g>`,shuttle:`<path d="M-28-12L-35-59 0-111 35-59 28-12Z" fill="${metal}" stroke="#243c46" stroke-width="3"/><path d="M-31-58L-68-12H-30M31-58L68-12H30" fill="${p.primary}" stroke="#263c44" stroke-width="3"/><path d="M-15-66L0-89 15-66 11-55H-11Z" fill="${glass}" stroke="#3d5664" stroke-width="3"/>`,tower:`<path d="M-34-12H34L28-64H-28Z" fill="${metal}" stroke="#243c46" stroke-width="3"/><rect x="-18" y="-55" width="36" height="24" rx="4" fill="${glass}"/><path d="M-20-65V-109M20-65V-99" stroke="#c6d3d6" stroke-width="4"/><path d="M-25-109H-15M15-99H25" stroke="${p.primary}" stroke-width="7"/><circle cx="-20" cy="-113" r="4" fill="${p.glass}"/>`})[c.cabin]||''}
function legsArt(c,p){const extra=extraLegs(c,p);if(extra!==null)return extra;const metal=p.hardware,dark='#526d78';let paths='',feet='';if(c.legs==='skids'){paths='<path d="M-49 48L-70 126M49 48L70 126"/>';feet='<path d="M-100 135H-49M49 135H100" stroke-width="11"/>'}else if(c.legs==='spider'){paths='<path d="M-52 42L-100 66-106 130M52 42L100 66 106 130M-46 58L-72 83-79 130M46 58L72 83 79 130"/>';feet='<path d="M-120 135H-94M94 135H120M-91 135H-68M68 135H91" stroke-width="7"/>'}else{paths=`<path d="M-50 43L-96 130M50 43L96 130"/>${c.legs==='braced'?'<path d="M-62 51L-68 95-96 128M62 51L68 95 96 128" stroke-width="3"/>':''}${c.legs==='spring'?'<path d="M-65 70l-13 4 8 9-16 3 7 10-15 4M65 70l13 4-8 9 16 3-7 10 15 4" stroke="#d5d9cf" stroke-width="4"/>':''}`;feet=c.legs==='boots'?'<path d="M-106 118H-83V129L-64 132V143H-121V134L-106 130ZM106 118H83V129L64 132V143H121V134L106 130Z" stroke-width="2"/>':'<path d="M-111 136H-80M80 136H111" stroke-width="9"/>'}return `<g stroke="${metal}" stroke-width="6" fill="none" stroke-linecap="round">${paths}</g><g fill="${p.foot}" stroke="${c.legs==='boots'?dark:p.foot}" stroke-linecap="round">${feet}</g><g fill="${dark}"><circle cx="-50" cy="43" r="7"/><circle cx="50" cy="43" r="7"/></g>`}
function engineArt(c,p,id){const extra=extraEngine(c,p,id);if(extra!==null)return extra;const bell=(x,w=21,y=66)=>`<g transform="translate(${x} ${y})"><path d="M-${w*.55} 0H${w*.55}L${w} 30H-${w}Z" fill="url(#${id}engine)" stroke="#182e37" stroke-width="2"/><path d="M-${w} 29H${w}" stroke="#a7bcc1" stroke-width="3"/></g>`;return ({bell:bell(0,26),twin:bell(-24,19)+bell(24,19),quad:[-43,-14,14,43].map(x=>bell(x,12)).join(''),spike:`<path d="M-31 65H31V81H-31Z" fill="url(#${id}engine)"/><path d="M-14 76H14L0 103Z" fill="${p.secondary}" stroke="#415c66" stroke-width="2"/>`,ion:`<path d="M-34 65H34L27 91H-27Z" fill="url(#${id}engine)" stroke="#1d333c" stroke-width="2"/><ellipse cy="91" rx="27" ry="7" fill="${p.glass}"/><path d="M-22 78H22" stroke="${p.secondary}" stroke-width="3"/>`})[c.engine]||''}
function flameArt(c,id){const d=c.details||defaultDetails(),color=d.flameColor||CATALOG.flame.find(o=>o.id===c.flame)?.color||'#8be1ef';if(c.flame==='off')return '';const xs=c.engine==='twin'?[-24,24]:c.engine==='quad'?[-43,-14,14,43]:c.engine==='triple'?[-33,0,33]:[0],w=c.engine==='quad'?7:c.engine==='twin'||c.engine==='triple'?12:18;return `<g transform="scale(${d.engineW} 1)">${xs.map(x=>`<g transform="translate(${x} 98) scale(1 ${d.flameLength})">${flamePaths(d.flameShape,w,color,`url(#${id}flame)`,d.flameCore)}</g>`).join('')}</g>`}
function stickerArt(c,part,id,thumb,selectedCategory,selectedSticker){return `<g clip-path="url(#${id}${part==='cabin'?'cabinSurface':'surface'})">${c.stickers.map((s,i)=>{if((s.part||'body')!==part)return '';const text=s.kind==='text',font=text?'ui-monospace,monospace':'Apple Color Emoji,Segoe UI Emoji,Noto Color Emoji,sans-serif';return `<g ${!thumb?`data-sticker="${i}"`:''} transform="translate(${s.x} ${s.y}) rotate(${s.rot})"><g transform="scale(${s.flip?-1:1} 1)"><text text-anchor="middle" dominant-baseline="central" font-size="${s.size}" fill="${s.color||'#f3e6c6'}" font-weight="${text?'700':'400'}" font-family="${font}">${escape(s.glyph)}</text></g>${!thumb&&i===selectedSticker&&selectedCategory==='stickers'?`<rect class="sticker-ring" x="${-s.size*.7}" y="${-s.size*.7}" width="${s.size*1.4}" height="${s.size*1.4}" rx="3"/>`:''}</g>`}).join('')}</g>`}

function renderCraft(c,{part=null,thumb=false,selectedCategory='',selectedSticker=-1,showFlame=true,flameOnly=false,shadow=true,fullView=false}={}){const p=palette(c),id='c'+(++serial),color=c.details?.flameColor||CATALOG.flame.find(o=>o.id===c.flame)?.color,d=c.details||defaultDetails();const bounds={cabin:'-95 -145 190 155',body:'-112 -30 224 115',legs:'-140 30 280 128',engine:'-85 57 170 95',flame:'-60 87 120 100'},view=part&&!fullView&&bounds[part]?bounds[part]:'-150 -140 300 325';const stickerClip=`<clipPath id="${id}surface"><path d="${bodyShape(c)}"/></clipPath><clipPath id="${id}cabinSurface"><path d="${cabinSurface(c)||''}"/></clipPath>`;let art='';const group=(key,content,outline)=>`<g ${!thumb?`data-part="${key}"`:''}>${content}${!thumb?`<rect class="part-outline ${selectedCategory===key?'selected':''}" x="${outline[0]}" y="${outline[1]}" width="${outline[2]}" height="${outline[3]}" rx="8"/>`:''}</g>`;
if(showFlame&&(!part||part==='flame'))art+=flameArt(c,id);
if(!flameOnly&&(!part||part==='legs'))art+=group('legs',legsArt(c,p),[-124,71,248,77]);
if(!flameOnly&&(!part||part==='engine'))art+=group('engine',`<g transform="scale(${d.engineW} 1)">${engineArt(c,p,id)}</g>`,[-61,70,122,35]);
if(!flameOnly&&(!part||part==='body'))art+=group('body',`<g transform="scale(${d.bodyW} 1)">${bodyArt(c,p,id)}${patternArt(c,p,id+'surface')}${stickerArt(c,'body',id,thumb,selectedCategory,selectedSticker)}</g>`,[-77,-13,154,82]);
if(!flameOnly&&(!part||part==='cabin'))art+=group('cabin',`<g transform="translate(0 -14) scale(${d.cabinW} ${d.cabinH}) translate(0 14)"><path d="M-35-19H35V-9H-35Z" fill="${p.dark}"/>${cabinArt(c,p,id)}${stickerArt(c,'cabin',id,thumb,selectedCategory,selectedSticker)}</g>`,[-58,-122,116,107]);

if(!flameOnly&&c.base==='car'&&!part)art+=`<g fill="#26373f" stroke="#879ba5" stroke-width="5"><circle cx="-66" cy="74" r="25"/><circle cx="66" cy="74" r="25"/></g>`;
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${view}" ${thumb?'aria-hidden="true"':`role="img" aria-label="${escape(c.name)} live craft preview"`}><defs><linearGradient id="${id}hull" x1="0" x2="1" y2=".5"><stop stop-color="${p.dark}"/><stop offset=".23" stop-color="${p.primary}"/><stop offset=".52" stop-color="${p.primary}"/><stop offset=".8" stop-color="${p.primary}"/><stop offset="1" stop-color="${p.dark}"/></linearGradient><linearGradient id="${id}metal"><stop stop-color="#677f8c"/><stop offset=".35" stop-color="${p.secondary}"/><stop offset=".7" stop-color="${p.secondary}"/><stop offset="1" stop-color="#8198a1"/></linearGradient><linearGradient id="${id}glass" x2=".8" y2="1"><stop stop-color="${p.glass}"/><stop offset=".3" stop-color="#436d7e"/><stop offset="1" stop-color="#122f40"/></linearGradient><linearGradient id="${id}engine"><stop stop-color="#2f4652"/><stop offset=".4" stop-color="${p.engine}"/><stop offset=".7" stop-color="#6d8792"/><stop offset="1" stop-color="#2a434e"/></linearGradient><linearGradient id="${id}flame" x1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".95"/><stop offset=".55" stop-color="${color}" stop-opacity=".65"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient>${stickerClip}</defs>${!part&&shadow&&!flameOnly?'<ellipse cy="149" rx="102" ry="10" fill="#06131b" opacity=".28"/>':''}${art}</svg>`}
export {renderCraft};

// A flight selection freezes its artwork. Later workshop edits cannot alter a running craft.
export async function createFlightImages(value){
 const craft=normalize(value);if(craft.base==='car')throw Error('Car concepts stay in the workshop. Choose the original Car for its special flight mechanics.');
 const width=768,height=832;
 async function raster(options){const svg=renderCraft(craft,{thumb:true,shadow:false,fullView:true,...options});const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('This craft could not be prepared for flight.'));image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)});const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.drawImage(image,0,0,width,height);return {canvas,context,image:canvas.toDataURL('image/png')}}
 const [body,flame,legs]=await Promise.all([raster({showFlame:false}),raster({flameOnly:true}),raster({part:'legs',showFlame:false})]);
 const pixels=legs.context.getImageData(0,0,width,height).data;let left=width,right=-1,bottom=-1;
 for(let y=0;y<height;y++)for(let x=0;x<width;x++)if(pixels[(y*width+x)*4+3]>32){left=Math.min(left,x);right=Math.max(right,x);bottom=Math.max(bottom,y)}
 if(bottom<0)throw Error('This craft needs visible landing gear.');
 const span=Math.max(width/2-left,right+1-width/2)*300/width,foot=(bottom+1)*325/height-140;
 if(span<70||span>145||foot<110||foot>160)throw Error('This landing gear cannot be prepared safely.');
 return {schema:1,id:craft.id,name:craft.name,revision:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),image:body.image,flame:craft.flame==='off'?'':flame.image,span,foot};
}

export function workshopThumbnail(value){return renderCraft(normalize(value),{thumb:true,shadow:false,showFlame:false})}
